import{_ as a,c as i,o as t,ag as n}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse(`{"title":"Guide de l'autorisation d'enregistrement de l'écran (macOS)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/screen-recording.md","filePath":"fr/guide/screen-recording.md","lastUpdated":1794112334000}`),r={name:"fr/guide/screen-recording.md"};function s(l,e,o,d,c,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="guide-de-l-autorisation-d-enregistrement-de-l-ecran-macos" tabindex="-1">Guide de l&#39;autorisation d&#39;enregistrement de l&#39;écran (macOS) <a class="header-anchor" href="#guide-de-l-autorisation-d-enregistrement-de-l-ecran-macos" aria-label="Permalink to &quot;Guide de l&#39;autorisation d&#39;enregistrement de l&#39;écran (macOS)&quot;">​</a></h1><h2 id="pourquoi-nicasa-a-t-il-besoin-de-l-autorisation-d-enregistrement-de-l-ecran" tabindex="-1">Pourquoi Nicasa a-t-il besoin de l&#39;autorisation d&#39;enregistrement de l&#39;écran ? <a class="header-anchor" href="#pourquoi-nicasa-a-t-il-besoin-de-l-autorisation-d-enregistrement-de-l-ecran" aria-label="Permalink to &quot;Pourquoi Nicasa a-t-il besoin de l&#39;autorisation d&#39;enregistrement de l&#39;écran ?&quot;">​</a></h2><p>Sous macOS, les applications de capture d&#39;écran doivent disposer de l&#39;autorisation d&#39;enregistrement de l&#39;écran pour pouvoir lire les pixels de l&#39;affichage.</p><p>Depuis macOS 10.15 Catalina, Apple a introduit des protections de confidentialité plus strictes. Toute application qui capture le contenu de l&#39;écran — y compris les captures d&#39;écran — doit être explicitement approuvée par l&#39;utilisateur.</p><p>Cela s&#39;applique à toutes les applications, y compris celles téléchargées depuis le Mac App Store.</p><p><strong>Sans cette autorisation, Nicasa ne peut ni prendre de captures d&#39;écran ni enregistrer le contenu de l&#39;écran.</strong></p><h2 id="comment-activer-l-autorisation-d-enregistrement-de-l-ecran" tabindex="-1">Comment activer l&#39;autorisation d&#39;enregistrement de l&#39;écran <a class="header-anchor" href="#comment-activer-l-autorisation-d-enregistrement-de-l-ecran" aria-label="Permalink to &quot;Comment activer l&#39;autorisation d&#39;enregistrement de l&#39;écran&quot;">​</a></h2><p>Suivez ces étapes :</p><ol><li>Ouvrez <strong>Réglages Système</strong></li><li>Allez dans <strong>Confidentialité et sécurité</strong></li><li>Sélectionnez <strong>Enregistrement de l&#39;écran</strong></li><li>Trouvez <strong>Nicasa</strong> dans la liste et cochez la case</li></ol><p>Si l&#39;application était déjà en cours d&#39;exécution, redémarrez Nicasa après avoir accordé l&#39;autorisation.</p><h2 id="si-la-demande-d-autorisation-n-est-pas-apparue" tabindex="-1">Si la demande d&#39;autorisation n&#39;est pas apparue <a class="header-anchor" href="#si-la-demande-d-autorisation-n-est-pas-apparue" aria-label="Permalink to &quot;Si la demande d&#39;autorisation n&#39;est pas apparue&quot;">​</a></h2><p>La boîte de dialogue apparaît généralement la première fois que l&#39;application tente de capturer l&#39;écran.</p><p>Si vous n&#39;avez pas vu la demande, cela peut être dû à :</p><ul><li>une demande d&#39;autorisation précédemment refusée</li><li>un état d&#39;autorisation mis en cache par macOS</li><li>une tentative de capture avant que la boîte de dialogue puisse s&#39;afficher</li></ul><p>Dans ce cas, vous devrez peut-être réinitialiser l&#39;autorisation.</p><h2 id="reinitialiser-l-autorisation-d-enregistrement-de-l-ecran" tabindex="-1">Réinitialiser l&#39;autorisation d&#39;enregistrement de l&#39;écran <a class="header-anchor" href="#reinitialiser-l-autorisation-d-enregistrement-de-l-ecran" aria-label="Permalink to &quot;Réinitialiser l&#39;autorisation d&#39;enregistrement de l&#39;écran&quot;">​</a></h2><p>Vous pouvez réinitialiser l&#39;autorisation avec la commande suivante dans le Terminal :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.nicasa.nue</span></span></code></pre></div><p>Après avoir exécuté la commande :</p><ol><li>Redémarrez Nicasa</li><li>Déclenchez à nouveau la fonction de capture</li><li>macOS devrait afficher de nouveau la demande d&#39;autorisation</li></ol><h2 id="si-la-reinitialisation-ne-fonctionne-pas" tabindex="-1">Si la réinitialisation ne fonctionne pas <a class="header-anchor" href="#si-la-reinitialisation-ne-fonctionne-pas" aria-label="Permalink to &quot;Si la réinitialisation ne fonctionne pas&quot;">​</a></h2><p>Dans de rares cas, macOS peut conserver un état d&#39;autorisation invalide.</p><p>Si la réinitialisation ne résout pas le problème, essayez les étapes suivantes :</p><ol><li>Quittez Nicasa</li><li>Supprimez Nicasa de votre dossier Applications</li><li>Réinstallez la dernière version depuis le Mac App Store</li><li>Relancez l&#39;application</li><li>Lorsque macOS demande l&#39;autorisation d&#39;enregistrement de l&#39;écran, sélectionnez <strong>Autoriser</strong></li></ol><p>Réinstaller l&#39;application peut forcer macOS à recréer l&#39;entrée d&#39;autorisation.</p><h2 id="solution-manuelle-alternative" tabindex="-1">Solution manuelle alternative <a class="header-anchor" href="#solution-manuelle-alternative" aria-label="Permalink to &quot;Solution manuelle alternative&quot;">​</a></h2><p>Vous pouvez également basculer l&#39;autorisation manuellement :</p><ol><li>Ouvrez <strong>Réglages Système</strong></li><li>Allez dans <strong>Confidentialité et sécurité</strong></li><li>Ouvrez <strong>Enregistrement de l&#39;écran</strong></li><li>Décochez Nicasa, puis cochez-le à nouveau</li><li>Redémarrez Nicasa</li></ol><h2 id="remarque-de-securite" tabindex="-1">Remarque de sécurité <a class="header-anchor" href="#remarque-de-securite" aria-label="Permalink to &quot;Remarque de sécurité&quot;">​</a></h2><p>Accorder l&#39;autorisation d&#39;enregistrement de l&#39;écran ne permet pas à Nicasa de contrôler votre système.</p><p>Elle permet uniquement à l&#39;application de lire les pixels de l&#39;écran pour les fonctions de capture.</p><p>Vous pouvez révoquer cette autorisation à tout moment dans : <strong>Réglages Système → Confidentialité et sécurité → Enregistrement de l&#39;écran</strong></p>',32)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
